WITH joined AS (SELECT a.id, a.category, a.brand, a.price, a.stock_qty, a.launch_date, a.tags, a.supplier_id, s.supplier_name FROM products a LEFT JOIN suppliers s ON a.supplier_id = s.id) SELECT s.id, s.category, s.launch_date, s.tags, s.supplier_id, (SELECT MIN(x.cost) FROM products x WHERE x.supplier_id = s.supplier_id) AS min_product_cost FROM joined s ORDER BY id DESC NULLS FIRST, launch_date DESC;
